/* M204 – Le marché (logiprof, leçons 4, 4.1 à 4.3).
   Objectifs définis par l'enseignant (leçon « M204 – Objectifs », sans code Swiss Logistics) : codés M204.1 à M204.7.
   a[0] = bonne réponse (mélangée à l'affichage). « Hors support » = complément vérifié hors du cours. */
const HS_LOG = "Hors support · défis logistiques selon la taille du marché";
const HS_ACC = "Hors support · accès aux marchés fermés";
const HS_CO = "Hors support · Code des obligations, art. 621 et 773";
const HS_POSTE = "Hors support · Poste CH, monopole résiduel";
const HS_MONO = "Hors support · effets d’un monopole";
window.OBJ = [
/* ============ 1 · ÉTUDE DE MARCHÉ ============ */
{code:"M204.1", t:"L’étude de marché", g:"Je peux analyser l’importance de l’étude de marché pour les entreprises, en identifiant les informations nécessaires à la prise de décision et en décrivant les méthodes utilisées pour recueillir ces données.", col:"teal", ic:"search",
ch:[
{k:"qcm",q:"Quel est le but principal d’une étude de marché ?",a:["Recueillir des informations pour décider de façon éclairée","Fixer les salaires de tous les collaborateurs pour l’année","Remplacer toute la publicité par des enquêtes en ligne","Supprimer définitivement la concurrence sur le marché"],ex:"Le but principal est de recueillir des informations pour prendre des décisions éclairées.",ref:"Leçon 4.1.2"},
{k:"multi",q:"Pourquoi l’étude de marché est-elle devenue nécessaire ?",good:["Concurrence accrue","Marchés saturés","Mondialisation","Renchérissement des matières premières"],bad:["Baisse du nombre de produits","Disparition de la concurrence"],ex:"Ce sont les quatre raisons du cours.",ref:"Leçon 4.1.1"},
{k:"tf",q:"Aujourd’hui, une entreprise peut se fier uniquement à son expérience passée pour connaître son marché.",v:false,ex:"Le marché est devenu plus grand et plus complexe : l’expérience ne suffit plus, il faut des méthodes de marketing.",ref:"Leçon 4.1"},
{k:"qcm",q:"Que signifie un « marché saturé » ?",a:["Les clients ont déjà ce qu’il faut : il faut innover","Il n’y a plus aucun produit en vente dans ce secteur","Les prix y sont fixés chaque année par l’État","Le marché est fermé aux entreprises étrangères"],ex:"Sur un marché saturé, avec des biens de substitution, l’entreprise doit innover.",ref:"Leçon 4.1.1"},
{k:"multi",q:"Quelles méthodes de recueil de données le cours cite-t-il ?",good:["Observation d’Internet","Lecture d’articles de presse","Entretiens avec des clients","Entretiens avec des fournisseurs"],bad:["Lecture des horoscopes","Tirage au sort des clients"],ex:"Observation (Internet, presse) et entretiens avec clients et fournisseurs.",ref:"Leçon 4.1.3"},
{k:"case",s:"L’entreprise EcoTextiles, qui vend des vêtements en fibres naturelles, voit ses ventes baisser.",q:"Quelles méthodes a-t-elle utilisées pour comprendre pourquoi ?",a:["Des enquêtes en ligne et des entretiens avec des clients fidèles","Une baisse de tous les prix sans rien demander à personne","Un changement complet de logo, de nom et de couleurs","Le licenciement d’une partie du personnel de vente"],ex:"EcoTextiles a mené des enquêtes en ligne et des entretiens avec ses clients fidèles.",ref:"Leçon 4.1.3"},
{k:"case",s:"L’étude d’EcoTextiles montre deux causes : peu de styles différents et des prix trop élevés par rapport à la concurrence.",q:"Quelle décision est cohérente avec ces résultats ?",a:["Diversifier les collections et revoir les prix","Abandonner les fibres naturelles pour du plastique","Augmenter encore les prix pour compenser la baisse","Fermer la boutique en ligne et garder un seul magasin"],ex:"EcoTextiles a diversifié ses collections et revu ses prix, en gardant ses standards écologiques.",ref:"Leçon 4.1.3"},
{k:"multi",q:"Quelles informations une étude de marché permet-elle d’identifier ?",good:["Les concurrents existants et potentiels","Les leaders d’opinion","Les nouvelles tendances","Les besoins du marché"],bad:["Les horaires du personnel","La couleur des camions"],ex:"Situation actuelle, personnes influentes, tendances et besoins.",ref:"Leçon 4.1.2"},
{k:"match",q:"Associez chaque objectif de l’étude à son contenu.",p:[["Situation actuelle","Concurrents directs et indirects"],["Nouvelles tendances","Évolution des préférences"],["Besoins du marché","Attentes actuelles et futures"],["Réduction des risques","Anticiper les erreurs de décision"]],ex:"Ce sont les objectifs spécifiques de l’étude de marché.",ref:"Leçon 4.1.2"},
{k:"qcm",q:"Qui sont des « personnes influentes » sur un marché ?",a:["Les leaders d’opinion et les grands distributeurs","Les apprentis de première année de l’entreprise","Les chauffeurs qui livrent les marchandises","Les nouveaux clients qui n’achètent qu’une fois"],ex:"Le cours cite les leaders d’opinion et les grands distributeurs.",ref:"Leçon 4.1.2"},
{k:"case",s:"Une entreprise de matériel de randonnée veut lancer un sac à dos pour les vélos électriques.",q:"Quelle question l’étude de marché doit-elle d’abord aider à répondre ?",a:["Ce produit répond-il à un besoin de clients ?","Quelle couleur aura le camion de livraison ?","Combien de places de parc compte le dépôt ?","Quel jour aura lieu la fête du personnel ?"],ex:"Une analyse précoce répond à des questions comme : offrons-nous quelque chose de nouveau ? Ciblons-nous un nouveau groupe ?",ref:"Leçon 4.1.1"},
{k:"order",q:"Remettez dans l’ordre la démarche suivie par EcoTextiles.",a:["Constater la baisse des ventes","Interroger les clients","Analyser les causes","Décider des changements","Adapter les collections et les prix"],ex:"De l’étude de marché à la décision, puis à l’action.",ref:"Leçon 4.1.3"},
{k:"tf",q:"Chaque changement de marché nécessite une étude approfondie.",v:true,ex:"Le cours le précise.",ref:"Leçon 4.1.1"},
{k:"qcm",q:"À quoi servent les prévisions de marché ?",a:["À orienter les activités commerciales","À calculer les heures supplémentaires","À fixer le loyer du dépôt","À remplacer l’inventaire du stock"],ex:"Les prévisions, basées sur l’étude de marché, orientent les activités commerciales.",ref:"Leçon 4.1.3"},
{k:"case",s:"Un concurrent ouvre une boutique en ligne qui vend les mêmes produits que votre entreprise, 10 % moins cher.",q:"Pourquoi une étude de marché est-elle utile ici ?",a:["Pour analyser la menace et réagir à temps","Pour copier exactement son site Internet","Pour attendre que le concurrent disparaisse","Pour baisser tous les salaires de 10 %"],ex:"Analyser opportunités et menaces et agir à temps est crucial.",ref:"Leçon 4.1.2"},
{k:"sort",q:"Concurrent direct ou indirect d’une entreprise de livraison de repas ?",c:["Direct","Indirect"],it:[["Une autre plateforme de livraison de repas",0],["Un supermarché qui vend des plats préparés",1],["Un restaurant qui livre lui-même",0],["Une cantine d’entreprise",1],["Un service de livraison concurrent",0],["Un magasin de produits surgelés",1]],ex:"Direct : même produit, même besoin. Indirect : autre solution au même besoin.",ref:"Leçon 4.1.2"},
{k:"odd",q:"Lequel n’est pas un objectif de l’étude de marché ?",a:["Augmenter le nombre de pauses","Identifier les concurrents","Repérer les tendances","Réduire les risques de décision"],ex:"Les trois autres sont des objectifs cités par le cours.",ref:"Leçon 4.1.2"},
{k:"fill",q:"L’étude de marché aide à minimiser les ___ de décisions incorrectes.",a:["risques","salaires","stocks","délais"],ex:"Elle permet une décision informée et l’anticipation des risques.",ref:"Leçon 4.1.2"},
{k:"case",s:"Une entreprise veut toucher les étudiants, un groupe de clients qu’elle n’a jamais servi.",q:"Que doit-elle faire avant de se lancer ?",a:["Étudier ce groupe : besoins, habitudes, concurrence","Lancer tout de suite une campagne nationale","Copier l’offre d’un concurrent sans réfléchir","Réduire ses prix sans connaître la demande"],ex:"Viser un nouveau groupe de clients fait partie des questions de l’analyse précoce.",ref:"Leçon 4.1.1"},
{k:"tf",q:"L’étude de marché aide à identifier des opportunités de croissance.",v:true,ex:"En résumé : comprendre la concurrence, identifier les opportunités, réduire les risques.",ref:"Leçon 4.1.2"},
{k:"case",s:"Le prix du coton a fortement augmenté cette année.",q:"Pour une entreprise textile, quelle raison d’étudier le marché est concernée ?",a:["Le renchérissement des matières premières","La saturation du marché du coton","La disparition de la concurrence","La baisse des salaires dans le secteur"],ex:"Le renchérissement des matières premières est une des raisons citées.",ref:"Leçon 4.1.1"},
{k:"case",s:"Votre chef vous demande de noter pendant un mois les remarques des clients lors des livraisons.",q:"À quoi ces informations peuvent-elles servir ?",a:["À alimenter l’étude de marché de l’entreprise","À rien : seule la vente compte pour l’entreprise","À sanctionner les clients qui se plaignent trop","À remplacer le bulletin de livraison signé"],ex:"Les entretiens avec les clients font partie des méthodes de recueil.",ref:"Leçon 4.1.3"},
{k:"qcm",q:"Que veut dire « biens de substitution » ?",a:["Des produits qui peuvent en remplacer d’autres","Des produits retirés définitivement de la vente","Des produits dont la vente est réservée à l’État","Des produits fabriqués uniquement à l’étranger"],ex:"Sur un marché saturé, les clients peuvent passer à un produit de remplacement : il faut innover.",ref:"Leçon 4.1.1"},
{k:"case",s:"Une petite entreprise n’a pas le budget pour un grand sondage.",q:"Quelle méthode peu coûteuse le cours propose-t-il ?",a:["Observer Internet et la presse, discuter avec clients et fournisseurs","Engager une grande agence internationale pendant une année","Envoyer un questionnaire papier à tous les ménages de Suisse","Renoncer à toute information et se fier à son intuition"],ex:"L’étude de marché peut s’appuyer sur l’observation et les entretiens.",ref:"Leçon 4.1.3"},
{k:"qcm",q:"Pourquoi faut-il agir à temps après une étude de marché ?",a:["Les opportunités et les menaces évoluent vite","Les résultats deviennent secrets après un mois","La loi l’impose dans un délai de trois jours","Les clients oublient leurs réponses"],ex:"Le cours souligne qu’agir à temps est crucial.",ref:"Leçon 4.1.2"}
]},
/* ============ 2 · LE BESOIN ============ */
{code:"M204.2", t:"Le besoin", g:"Je peux expliquer le concept de besoin dans la création d’un marché, en décrivant comment il influence la demande et en donnant des exemples de besoins spécifiques ayant conduit à la création de nouveaux produits ou services.", col:"indigo", ic:"bulb",
ch:[
{k:"qcm",q:"Selon le cours, qu’est-ce qu’un besoin ?",a:["L’envie de combler un manque","Le prix de vente d’un produit","Un stock de marchandises au dépôt","Une obligation fixée par la loi"],ex:"Un besoin est l’envie de combler un manque ; le satisfaire élimine le manque.",ref:"Leçon 4"},
{k:"tf",q:"Pour qu’un marché se crée, il faut un besoin.",v:true,ex:"Le marché naît d’un besoin.",ref:"Leçon 4"},
{k:"multi",q:"Selon quoi les besoins varient-ils ?",good:["L’âge","Le pays","La profession","Le lieu","L’époque"],bad:["La couleur des yeux","Le jour de la semaine"],ex:"Le cours cite l’âge, le pays, la profession, le lieu et l’époque.",ref:"Leçon 4"},
{k:"case",s:"Un entrepreneur constate que beaucoup de personnes veulent stocker leurs photos et documents chez elles, sans dépendre d’Internet.",q:"Quel produit a-t-il pu développer à partir de ce besoin ?",a:["Des disques durs de stockage externes (NAS)","Des imprimantes à jet d’encre pour le bureau","Des clés de voiture électroniques sans contact","Des abonnements de téléphonie mobile illimités"],ex:"C’est l’exemple du cours : un besoin identifié devient un modèle d’entreprise.",ref:"Leçon 4"},
{k:"qcm",q:"Que se passe-t-il quand un besoin est satisfait ?",a:["Le manque disparaît","Le besoin double","Le prix baisse forcément","Le marché ferme"],ex:"La satisfaction du besoin élimine le manque.",ref:"Leçon 4"},
{k:"order",q:"Remettez dans l’ordre l’évolution des échanges décrite par le cours.",a:["Récolter et stocker des céréales sauvages","Se spécialiser (poterie, outils)","Échanger le surplus contre de la nourriture","Négocier le meilleur prix","Se rencontrer sur des marchés"],ex:"Du néolithique à la fin de l’âge du bronze, les échanges ont donné naissance aux marchés.",ref:"Leçon 4"},
{k:"qcm",q:"À la fin de l’âge du bronze, qu’est-ce qui devient crucial dans l’échange ?",a:["La négociation pour obtenir le meilleur prix","L’emballage soigné de chaque marchandise","La publicité diffusée à la radio régionale","Le transport rapide des marchandises par avion"],ex:"La négociation devient cruciale pour obtenir le meilleur prix.",ref:"Leçon 4"},
{k:"case",s:"Avec le télétravail, beaucoup de personnes cherchent des chaises de bureau confortables pour la maison.",q:"Que montre cet exemple ?",a:["Un nouveau besoin crée une demande pour un produit","Les besoins ne changent jamais avec l’époque","Le télétravail a fait disparaître le marché","Seuls les bureaux d’entreprise achètent des chaises"],ex:"Les besoins varient selon l’époque et le lieu ; ils influencent la demande.",ref:"Leçon 4"},
{k:"sort",q:"Ce besoin dépend surtout de…",c:["L’âge","Le lieu","La profession"],it:[["Une poussette pour un bébé",0],["Des chaînes à neige en montagne",1],["Des chaussures de sécurité au dépôt",2],["Un appareil auditif à 80 ans",0],["Un parasol au bord du lac",1],["Un logiciel de gestion de stock",2]],ex:"Les besoins varient selon l’âge, le lieu ou la profession.",ref:"Leçon 4"},
{k:"tf",q:"Les besoins sont les mêmes pour tout le monde, partout et à toutes les époques.",v:false,ex:"Ils varient selon l’âge, le pays, la profession, le lieu et l’époque.",ref:"Leçon 4"},
{k:"match",q:"Associez chaque besoin au produit ou service qu’il a fait naître.",p:[["Stocker ses fichiers chez soi","Disque dur externe (NAS)"],["Recevoir ses achats à domicile","Livraison de colis"],["Payer sans argent liquide","Paiement par carte"],["Se déplacer sans voiture","Vélo en libre-service"]],ex:"Un besoin identifié peut devenir un modèle d’entreprise.",ref:"Leçon 4 · exemples (hors support sauf NAS)"},
{k:"case",s:"Les achats en ligne augmentent fortement. Les clients veulent recevoir leurs colis même quand ils sont absents.",q:"Quel service répond à ce besoin ?",a:["Des consignes à colis accessibles 24 h sur 24","Des magasins fermés tous les samedis","Des catalogues papier plus épais chaque année","Des livraisons organisées seulement le dimanche"],ex:"Un besoin nouveau fait naître un service nouveau.",ref:"Leçon 4 · exemple (hors support)"},
{k:"qcm",q:"Comment le besoin influence-t-il la demande ?",a:["Plus le besoin est fort, plus la demande augmente","Le besoin n’a aucun effet sur la demande des clients","Un besoin très fort fait au contraire baisser la demande","La demande dépend seulement de la météo du jour"],ex:"Sans besoin, pas de demande ; un besoin fort fait monter la demande.",ref:"Leçon 4"},
{k:"fill",q:"Un marché naît d’un ___, l’envie de combler un manque.",a:["besoin","stock","contrat","prix"],ex:"C’est le point de départ de tout marché.",ref:"Leçon 4"},
{k:"case",s:"Dans un pays chaud, une entreprise suisse veut vendre ses chauffages électriques d’appoint.",q:"Que risque-t-elle ?",a:["De ne pas trouver de besoin, donc peu de demande","De vendre beaucoup plus que sur le marché suisse","De créer immédiatement un monopole dans ce pays","De devoir baisser les salaires de son personnel"],ex:"Les besoins varient selon le pays et le lieu.",ref:"Leçon 4"},
{k:"odd",q:"Lequel n’est pas un facteur qui fait varier les besoins selon le cours ?",a:["La couleur des cheveux","L’âge","La profession","L’époque"],ex:"Le cours cite l’âge, le pays, la profession, le lieu et l’époque.",ref:"Leçon 4"},
{k:"qcm",q:"Quels marchés existent encore aujourd’hui, selon le cours ?",a:["Marchés de légumes, de poissons et de Noël","Uniquement les grands marchés boursiers mondiaux","Uniquement les marchés en ligne sur Internet","Aucun : les marchés ont tous disparu depuis longtemps"],ex:"Le cours cite les marchés de légumes, de poissons et de Noël.",ref:"Leçon 4"},
{k:"case",s:"Une entreprise lance des boîtes de repas à cuisiner, livrées avec les ingrédients exacts, pour les personnes pressées.",q:"Quel besoin a-t-elle identifié ?",a:["Cuisiner sainement sans perdre de temps aux courses","Manger chaque jour au restaurant du quartier","Acheter davantage de vaisselle pour la cuisine","Faire ses courses au supermarché tous les jours"],ex:"Identifier un besoin précis permet de créer un produit nouveau.",ref:"Leçon 4 · exemple (hors support)"},
{k:"tf",q:"Au néolithique, les produits non nécessaires étaient échangés contre de la nourriture.",v:true,ex:"Avec la spécialisation (poterie, outils, taille de pierre), le surplus s’échange contre de la nourriture.",ref:"Leçon 4"},
{k:"case",s:"Un logisticien remarque que ses clients demandent souvent des emballages réutilisables.",q:"Que peut faire son entreprise de cette observation ?",a:["Proposer un service d’emballages consignés","Ignorer cette demande des clients","Doubler le prix des cartons jetables","Interdire les emballages réutilisables"],ex:"Repérer un besoin, c’est l’occasion de créer une offre.",ref:"Leçon 4 · exemple (hors support)"},
{k:"qcm",q:"Pourquoi l’époque fait-elle varier les besoins ?",a:["Les modes de vie et les techniques changent","Les gens oublient leurs anciens besoins","Le prix de l’or change chaque année","Les lois interdisent les anciens besoins"],ex:"Un besoin d’aujourd’hui (recharger un téléphone) n’existait pas il y a 50 ans.",ref:"Leçon 4"},
{k:"multi",q:"Lesquels sont des exemples de besoins qui ont créé de nouveaux services ?",good:["Recevoir ses colis en point relais","Payer avec son téléphone","Suivre son colis en ligne"],bad:["Attendre un colis sans information","Payer seulement en espèces"],ex:"Chacun de ces services répond à un besoin récent.",ref:"Leçon 4 · exemples (hors support)"},
{k:"case",s:"Le nombre de personnes âgées augmente en Suisse.",q:"Quel marché pourrait se développer ?",a:["La livraison de courses à domicile pour seniors","La vente de poussettes de sport pour bébés","Les jouets pour enfants de trois ans","Les manuels scolaires pour apprentis de 1re année"],ex:"Les besoins varient selon l’âge : une population plus âgée crée de nouveaux besoins.",ref:"Leçon 4"},
{k:"qcm",q:"Qu’est-ce qui transforme un besoin en marché ?",a:["La rencontre entre une offre et une demande","Une décision prise seule par le gouvernement","La fermeture des magasins de la concurrence","La baisse des salaires dans tout le secteur"],ex:"Un marché réunit marchands et acheteurs autour d’un besoin.",ref:"Leçon 4"},
{k:"case",s:"Pendant une vague de chaleur, les ventes de ventilateurs explosent.",q:"Que montre cette situation ?",a:["Un besoin soudain fait monter la demande","Le besoin n’a aucun lien avec la météo","Les ventilateurs sont un monopole","La demande baisse quand il fait chaud"],ex:"Le besoin influence directement la demande.",ref:"Leçon 4"}
]},
/* ============ 3 · FORMES DE MARCHÉ ============ */
{code:"M204.3", t:"Les formes de marché", g:"Je peux comparer les types de marchés (monopole, oligopole, polypole) en expliquant leurs caractéristiques et en évaluant leur impact sur la concurrence et les stratégies des entreprises.", col:"violet", ic:"nodes",
ch:[
{k:"match",q:"Associez chaque forme de marché à sa définition.",p:[["Monopole","Un seul fournisseur"],["Oligopole","Quelques fournisseurs"],["Polypole","Beaucoup de fournisseurs et de demandeurs"],["Monopsone","Un seul demandeur"]],ex:"Les formes de marché décrivent la structure de l’offre et de la demande.",ref:"Leçon 4.2.2"},
{k:"qcm",q:"Quel exemple le cours donne-t-il pour un monopole ?",a:["Les conduites d’eau","Le marché hebdomadaire","Le logement","Le pétrole"],ex:"Gazoducs, conduites d’eau, réseau de transport.",ref:"Leçon 4.2.2"},
{k:"qcm",q:"Quel exemple le cours donne-t-il pour un oligopole ?",a:["Le réseau mobile","Le marché hebdomadaire","Les conduites d’eau","Un employeur unique"],ex:"Pétrole, électricité, réseau mobile.",ref:"Leçon 4.2.2"},
{k:"qcm",q:"Quel exemple le cours donne-t-il pour un polypole ?",a:["Le marché hebdomadaire","Le gazoduc régional","Le réseau de téléphonie mobile","L’électricité du pays"],ex:"Marché hebdomadaire, logement.",ref:"Leçon 4.2.2"},
{k:"sort",q:"Classez chaque marché selon sa forme.",c:["Monopole","Oligopole","Polypole"],it:[["Réseau de conduites d’eau",0],["Opérateurs de téléphonie mobile",1],["Stands du marché du samedi",2],["Gazoduc régional",0],["Compagnies pétrolières",1],["Location d’appartements en ville",2]],ex:"Un seul fournisseur, quelques fournisseurs ou beaucoup de fournisseurs.",ref:"Leçon 4.2.2"},
{k:"tf",q:"Dans un polypole, la concurrence libre influence l’assortiment et les prix.",v:true,ex:"Beaucoup de fournisseurs et de demandeurs : la concurrence joue librement.",ref:"Leçon 4.2.2"},
{k:"qcm",q:"Qu’est-ce qu’un monopsone ?",a:["Un seul demandeur face à de nombreux offreurs","Un seul fournisseur face à de nombreux clients","Deux fournisseurs qui s’entendent sur les prix","Un marché sans aucun demandeur"],ex:"Le monopsone est rare : par exemple un employeur face à plusieurs candidats.",ref:"Leçon 4.2.2"},
{k:"case",s:"Dans une vallée isolée, une seule grande usine embauche. Une cinquantaine de personnes cherchent du travail.",q:"De quelle forme de marché du travail s’agit-il ?",a:["Un monopsone","Un polypole","Un oligopole","Un marché ouvert"],ex:"Un seul demandeur de travail (l’employeur) face à de nombreux offreurs.",ref:"Leçon 4.2.2"},
{k:"case",s:"Sur un marché hebdomadaire, dix stands vendent des pommes. Un vendeur augmente fortement son prix.",q:"Que risque-t-il ?",a:["Les clients achètent chez les autres stands","Les clients doivent payer, ils n’ont pas le choix","Les autres stands doivent fermer","Le prix des pommes augmente partout"],ex:"Dans un polypole, la concurrence limite les prix.",ref:"Leçon 4.2.2"},
{k:"case",s:"Trois opérateurs se partagent le réseau mobile suisse. L’un baisse ses prix.",q:"Quelle réaction est probable des deux autres ?",a:["Ils observent et adaptent souvent leurs prix","Ils ne réagissent jamais à ce changement","Ils quittent aussitôt le marché suisse","Ils deviennent ensemble un monopole légal"],ex:"Dans un oligopole, chaque fournisseur surveille de près les quelques autres.",ref:"Leçon 4.2.2 · stratégie (hors support)"},
{k:"qcm",q:"Dans quelle forme de marché la concurrence est-elle la plus forte ?",a:["Le polypole","Le monopole","L’oligopole","Le monopsone"],ex:"Beaucoup de fournisseurs : chacun doit se démarquer par l’assortiment et le prix.",ref:"Leçon 4.2.2"},
{k:"qcm",q:"Dans quelle forme de marché n’y a-t-il aucune concurrence entre fournisseurs ?",a:["Le monopole","Le polypole","L’oligopole","Le marché hebdomadaire"],ex:"Un seul fournisseur, sans concurrence.",ref:"Leçon 4.2.2"},
{k:"order",q:"Classez ces formes de marché, du plus petit au plus grand nombre de fournisseurs.",a:["Monopole","Oligopole","Polypole"],ex:"Un seul, quelques-uns, beaucoup.",ref:"Leçon 4.2.2"},
{k:"case",s:"Votre entreprise de transport est l’une des centaines de petites sociétés de déménagement du pays.",q:"Quelle stratégie est adaptée ?",a:["Se démarquer par le service, la qualité ou le prix","Fixer librement des prix très élevés","Attendre que les clients viennent seuls","S’entendre en secret avec tous les concurrents"],ex:"Dans un polypole, il faut se distinguer de nombreux concurrents.",ref:"Leçon 4.2.2 · stratégie (hors support)"},
{k:"odd",q:"Lequel n’est pas une forme de marché du cours ?",a:["Le multipole","Le monopole","L’oligopole","Le polypole"],ex:"Le cours cite monopole, oligopole, polypole et monopsone.",ref:"Leçon 4.2.2"},
{k:"fill",q:"Un marché avec quelques fournisseurs et une demande importante est un ___.",a:["oligopole","monopole","polypole","monopsone"],ex:"Oligopole : pétrole, électricité, réseau mobile.",ref:"Leçon 4.2.2"},
{k:"tf",q:"Le monopsone est une forme de marché fréquente.",v:false,ex:"Le cours le décrit comme rare.",ref:"Leçon 4.2.2"},
{k:"case",s:"Une compagnie gère seule le réseau de distribution d’eau d’une ville.",q:"Pourquoi n’y a-t-il pas plusieurs réseaux concurrents ?",a:["Construire plusieurs réseaux d’eau coûterait trop cher","La loi interdit de boire l’eau d’un fournisseur concurrent","Les habitants de la ville refusent toute forme de concurrence","L’eau potable ne peut pas se vendre aux particuliers"],ex:"Pour les réseaux (eau, gaz, rail), un seul réseau est souvent plus rationnel : c’est un monopole.",ref:"Leçon 4.2.2 · " + HS_MONO},
{k:"multi",q:"Quels exemples du cours sont des oligopoles ?",good:["Pétrole","Électricité","Réseau mobile"],bad:["Marché hebdomadaire","Logement"],ex:"Quelques grands fournisseurs dominent ces marchés.",ref:"Leçon 4.2.2"},
{k:"case",s:"Une nouvelle petite entreprise veut vendre du pétrole brut en Suisse.",q:"Quelle difficulté rencontrera-t-elle sur ce marché ?",a:["Quelques grands fournisseurs dominent déjà le marché","Aucune : il y a des milliers de petits concurrents","Le marché suisse du pétrole est un monopsone","Il n’y a plus aucune demande de pétrole en Suisse"],ex:"Le pétrole est un oligopole : entrer face à quelques géants est difficile.",ref:"Leçon 4.2.2"},
{k:"qcm",q:"Quel effet le nombre de fournisseurs a-t-il sur le client ?",a:["Plus il y a de fournisseurs, plus le client a le choix","Le nombre de fournisseurs n’a aucun effet","Moins il y a de fournisseurs, plus les prix baissent","Le client choisit toujours le monopole"],ex:"La concurrence élargit le choix et pèse sur les prix.",ref:"Leçon 4.2.2"},
{k:"case",s:"Vous cherchez un appartement en ville. Des dizaines de propriétaires proposent des logements.",q:"De quelle forme de marché s’agit-il ?",a:["Un polypole","Un monopole","Un oligopole","Un monopsone"],ex:"Le logement est un exemple de polypole dans le cours.",ref:"Leçon 4.2.2"},
{k:"qcm",q:"Comment la structure de l’offre et de la demande détermine-t-elle la forme de marché ?",a:["Par le nombre de fournisseurs et de demandeurs","Par la couleur et la forme des produits vendus","Par la taille des entrepôts des fournisseurs","Par l’âge moyen des clients de ce marché"],ex:"Les formes de marché décrivent cette structure.",ref:"Leçon 4.2.2"},
{k:"case",s:"Deux grandes chaînes de supermarchés se partagent la plupart des ventes alimentaires d’un pays.",q:"Comment qualifier ce marché ?",a:["Un oligopole","Un polypole parfait","Un monopsone","Un marché fermé"],ex:"Quelques grands fournisseurs dominent : c’est un oligopole.",ref:"Leçon 4.2.2"},
{k:"tf",q:"Dans un monopole, l’entreprise n’a pas besoin de se battre contre des concurrents pour garder ses clients.",v:true,ex:"Sans concurrence, la pression pour baisser les prix ou innover est faible.",ref:"Leçon 4.2.2 · " + HS_MONO}
]},
/* ============ 4 · CLASSER LES MARCHÉS ============ */
{code:"M204.4", t:"Classer les marchés", g:"Je peux décrire les critères de classification des marchés, tels que les objets échangés, les fonctions et l’accès, en donnant des exemples concrets pour chaque catégorie.", col:"coral", ic:"tags",
ch:[
{k:"multi",q:"Selon quels critères le cours classe-t-il les marchés ?",good:["L’objet ou le service échangé","La fonction","Le type d’accès"],bad:["La couleur du logo","Le nombre d’employés"],ex:"Objet ou service, fonction (approvisionnement ou vente) et accès (ouvert, fermé, limité).",ref:"Leçon 4.2.1"},
{k:"match",q:"Associez chaque marché à un exemple.",p:[["Biens de consommation","Vêtements et alimentation"],["Travail","Offre et demande d’emplois"],["Monétaire","Crédits à court terme des banques"],["Immobilier","Terrains et bâtiments"]],ex:"Ce sont les types de marché selon l’objet échangé.",ref:"Leçon 4.2.1"},
{k:"sort",q:"Classez chaque échange selon le type de marché.",c:["Biens de consommation","Services","Immobilier"],it:[["Acheter un livre",0],["Consulter un avocat",1],["Acheter un terrain",2],["Acheter un ordinateur",0],["Recevoir des soins",1],["Louer un entrepôt",2]],ex:"Objet matériel, prestation ou bien immobilier.",ref:"Leçon 4.2.1"},
{k:"qcm",q:"Quels sont les deux marchés selon la fonction ?",a:["Le marché d’approvisionnement et le marché de vente","Le marché local et le marché global du même produit","Le marché ouvert et le marché fermé par l’État","Le monopole et le polypole d’un même secteur"],ex:"L’entreprise achète sur le marché d’approvisionnement et vend sur le marché de vente.",ref:"Leçon 4.2.1"},
{k:"case",s:"Votre entreprise achète des cartons et du film étirable à un fournisseur, puis vend des colis préparés à des magasins.",q:"Sur quel marché achète-t-elle les cartons ?",a:["Le marché d’approvisionnement","Le marché de la vente","Le marché monétaire des banques","Le marché du travail"],ex:"Acheter ce dont on a besoin : c’est le marché d’approvisionnement.",ref:"Leçon 4.2.1"},
{k:"match",q:"Associez chaque type d’accès à un exemple du cours.",p:[["Ouvert","Caisses d’assurance maladie"],["Fermé","Poste et CFF"],["Limité","Taxis avec concession"]],ex:"L’accès peut être libre, fermé par des règles ou limité par des conditions.",ref:"Leçon 4.2.1"},
{k:"qcm",q:"Qu’est-ce qu’un marché ouvert ?",a:["Un marché accessible sans restriction","Un marché ouvert seulement le samedi","Un marché réservé à l’État","Un marché sans aucun client"],ex:"Exemple du cours : les caisses d’assurance maladie.",ref:"Leçon 4.2.1"},
{k:"qcm",q:"Qu’est-ce qu’un marché fermé ?",a:["Un marché à l’accès limité par des règles","Un marché qui a fait faillite l’an passé","Un marché qui ne vend que pendant la nuit","Un marché où il n’y a aucun fournisseur"],ex:"Des règles économiques ou juridiques limitent l’accès : par exemple certains services publics.",ref:"Leçon 4.2.1"},
{k:"case",s:"Une ville limite le nombre de taxis en accordant des concessions, pour éviter la saturation.",q:"Quel type d’accès au marché est-ce ?",a:["Un marché limité","Un marché ouvert","Un marché d’approvisionnement","Un marché monétaire"],ex:"C’est l’exemple du cours pour un marché limité.",ref:"Leçon 4.2.1"},
{k:"tf",q:"Le marché du travail concerne l’offre et la demande de force de travail.",v:true,ex:"C’est un des types de marché selon l’objet.",ref:"Leçon 4.2.1"},
{k:"qcm",q:"Sur quel marché une banque accorde-t-elle des crédits à court terme ?",a:["Le marché monétaire","Le marché immobilier","Le marché du travail","Le marché de vente"],ex:"Le marché monétaire concerne les crédits à court terme des banques.",ref:"Leçon 4.2.1"},
{k:"case",s:"Vous cherchez un poste de logisticien·ne après votre CFC. Plusieurs entreprises publient des offres d’emploi.",q:"Sur quel marché vous trouvez-vous ?",a:["Le marché du travail","Le marché des services","Le marché monétaire","Le marché immobilier"],ex:"Vous offrez votre force de travail ; les entreprises la demandent.",ref:"Leçon 4.2.1"},
{k:"odd",q:"Lequel n’est pas un type de marché selon l’objet ?",a:["Le marché limité","Le marché immobilier","Le marché du travail","Le marché monétaire"],ex:"« Limité » est un type d’accès, pas un objet échangé.",ref:"Leçon 4.2.1"},
{k:"fill",q:"Les matières premières et l’art font partie des ___ marchés.",a:["autres","fermés","monétaires","immobiliers"],ex:"Le cours les classe dans « autres ».",ref:"Leçon 4.2.1"},
{k:"case",s:"Une galerie vend des tableaux lors d’une vente aux enchères.",q:"Dans quelle catégorie du cours ce marché se classe-t-il ?",a:["Autres marchés (art)","Biens de consommation","Marché du travail","Marché monétaire"],ex:"L’art figure dans les « autres marchés ».",ref:"Leçon 4.2.1"},
{k:"order",q:"Pour une entreprise de vélos, remettez dans l’ordre le passage d’un marché à l’autre.",a:["Acheter cadres et roues (approvisionnement)","Assembler les vélos","Stocker les vélos finis","Vendre aux magasins (vente)"],ex:"L’entreprise achète sur le marché d’approvisionnement et vend sur le marché de vente.",ref:"Leçon 4.2.1"},
{k:"case",s:"Une entreprise de logistique loue un nouvel entrepôt de 5000 m².",q:"Sur quel marché agit-elle ?",a:["Le marché immobilier","Le marché des biens de consommation","Le marché monétaire","Le marché de vente"],ex:"Terrains et bâtiments relèvent du marché immobilier.",ref:"Leçon 4.2.1"},
{k:"multi",q:"Quels exemples sont des services selon le cours ?",good:["Conseils juridiques","Soins","Divertissement"],bad:["Terrains","Livres"],ex:"Les services sont des prestations, pas des objets.",ref:"Leçon 4.2.1"},
{k:"tf",q:"Une même entreprise peut agir à la fois sur un marché d’approvisionnement et sur un marché de vente.",v:true,ex:"Elle achète d’un côté et vend de l’autre.",ref:"Leçon 4.2.1"},
{k:"case",s:"Un particulier veut ouvrir un bureau de poste privé pour distribuer des lettres de 20 g.",q:"Que va-t-il constater ?",a:["C’est un marché fermé : l’accès est réservé","C’est un marché ouvert : il peut commencer demain","C’est un marché d’approvisionnement","C’est un marché monétaire"],ex:"Certains services publics, comme ceux de la Poste, sont des marchés fermés.",ref:"Leçon 4.2.1 · " + HS_POSTE},
{k:"qcm",q:"Pourquoi limiter le nombre de taxis par des concessions ?",a:["Pour éviter la saturation du marché","Pour augmenter le nombre de taxis","Pour supprimer toute concurrence","Pour baisser le prix de l’essence"],ex:"Le cours le précise : éviter la saturation.",ref:"Leçon 4.2.1"},
{k:"case",s:"Un assuré change de caisse d’assurance maladie chaque année pour payer moins cher.",q:"Que montre cet exemple sur le type d’accès ?",a:["Le marché est ouvert : il peut choisir librement","Le marché est fermé : il ne peut pas changer","Le marché est limité par des concessions","Le marché est un monopole d’État"],ex:"Les caisses d’assurance maladie sont l’exemple de marché ouvert du cours.",ref:"Leçon 4.2.1"},
{k:"qcm",q:"Dans quel marché classez-vous l’achat d’un téléphone portable ?",a:["Biens de consommation","Services aux personnes","Marché immobilier","Marché monétaire"],ex:"L’électronique fait partie des biens de consommation.",ref:"Leçon 4.2.1"},
{k:"case",s:"Votre entreprise négocie avec une banque un crédit de trois mois pour financer un stock de Noël.",q:"Sur quel marché négocie-t-elle ?",a:["Le marché monétaire","Le marché du travail","Le marché immobilier","Le marché de vente"],ex:"Crédits à court terme des banques : marché monétaire.",ref:"Leçon 4.2.1"},
{k:"case",s:"Un dépôt engage cinq apprentis logisticiens pour la rentrée.",q:"Sur quel marché l’entreprise agit-elle comme demandeuse ?",a:["Le marché du travail","Le marché des services","Le marché immobilier","Le marché monétaire"],ex:"L’entreprise demande de la force de travail.",ref:"Leçon 4.2.1"}
]},
/* ============ 5 · TAILLE DU MARCHÉ ============ */
{code:"M204.5", t:"La taille du marché", g:"Je peux expliquer les défis logistiques liés à la taille d’un marché, en comparant les spécificités des marchés locaux, régionaux, nationaux et globaux.", col:"amber", ic:"globe",
ch:[
{k:"order",q:"Classez les marchés du plus petit au plus grand.",a:["Local","Régional","National","International","Global"],ex:"Ce sont les cinq groupes de la taille géographique.",ref:"Leçon 4.3.1"},
{k:"match",q:"Associez chaque taille de marché à l’exemple du cours.",p:[["Local","Magasin de village"],["Régional","Marché hebdomadaire"],["National","Téléphonie mobile suisse"],["Global","Marché financier"]],ex:"Ce sont les exemples de la leçon 4.3.1.",ref:"Leçon 4.3.1"},
{k:"qcm",q:"Quel exemple le cours donne-t-il pour un marché international ?",a:["Le marché de l’Union européenne","Le magasin du village","Le marché hebdomadaire régional","Le marché financier mondial"],ex:"International : l’UE. Global : le marché financier.",ref:"Leçon 4.3.1"},
{k:"multi",q:"Par quoi la taille d’un marché est-elle déterminée ?",good:["Son étendue géographique","Le nombre de clients potentiels"],bad:["La taille du logo","Le nombre de camions"],ex:"Étendue géographique ou nombre de clients potentiels.",ref:"Leçon 4.3"},
{k:"case",s:"Une boulangerie de village livre ses clients à vélo dans un rayon de 3 km.",q:"Quel est l’avantage logistique de ce marché local ?",a:["Des trajets courts et un contact direct avec les clients","Des envois réguliers par conteneur maritime vers l’Asie","Des formalités de douane complexes à chaque livraison","Des délais de livraison de plusieurs semaines"],ex:"Marché local : distances courtes, relations directes.",ref:HS_LOG},
{k:"case",s:"Une entreprise suisse commence à vendre ses produits au Japon.",q:"Quel défi logistique nouveau apparaît ?",a:["Douane, transport long et réglementations différentes","Aucun : c’est comme livrer en ville à côté du dépôt","Seulement un changement de couleur de l’emballage","Il suffit de livrer à vélo un peu plus loin qu’avant"],ex:"Sur un marché global, il faut gérer douane, longues distances et règles différentes.",ref:HS_LOG},
{k:"qcm",q:"Pourquoi la taille du marché influence-t-elle le marketing ?",a:["La stratégie doit s’adapter au nombre et au lieu des clients","La taille du marché n’a aucun effet sur le marketing","Seuls les tout petits marchés ont besoin de marketing","Le marketing est exactement le même dans tous les pays"],ex:"La classification aide à adapter la stratégie.",ref:"Leçon 4.3"},
{k:"case",s:"Un magasin de vélos de quartier veut attirer plus de clients.",q:"Quelle stratégie convient à son marché local ?",a:["Des campagnes ciblées et des relations directes","Une publicité télévisée diffusée dans le monde entier","Un site Internet traduit en vingt langues étrangères","Des entrepôts répartis sur trois continents"],ex:"Une entreprise locale mise sur des campagnes ciblées et des relations directes.",ref:"Leçon 4.3.1"},
{k:"multi",q:"Quels facteurs une entreprise globale doit-elle prendre en compte ?",good:["Facteurs culturels","Facteurs économiques","Facteurs réglementaires"],bad:["Seulement la météo locale","Seulement l’avis du voisin"],ex:"Le cours cite des facteurs culturels, économiques et réglementaires diversifiés.",ref:"Leçon 4.3.1"},
{k:"sort",q:"Classez chaque entreprise selon la taille de son marché.",c:["Local","National","Global"],it:[["Une épicerie de quartier",0],["Un opérateur de téléphonie suisse",1],["Une banque active sur les bourses mondiales",2],["Un coiffeur de village",0],["Une chaîne de magasins présente dans toute la Suisse",1],["Un fabricant de montres vendu dans 80 pays",2]],ex:"Du village au monde entier.",ref:"Leçon 4.3.1"},
{k:"tf",q:"Livrer sur un marché national demande souvent un réseau de centres de distribution régionaux.",v:true,ex:"Plus le marché est grand, plus le réseau logistique doit être organisé.",ref:HS_LOG},
{k:"case",s:"Une PME vaudoise vend désormais dans toute la Suisse. Ses clients sont à Genève, Bâle, Lugano et Coire.",q:"Quel défi logistique doit-elle gérer ?",a:["Organiser les tournées et les délais dans plusieurs régions","Passer chacun de ses colis à la douane suisse","Traduire tous ses produits en japonais et en chinois","Livrer tous ses clients à pied depuis Lausanne"],ex:"Un marché national demande une planification des transports à l’échelle du pays.",ref:HS_LOG},
{k:"odd",q:"Lequel n’est pas un défi typique d’un marché global ?",a:["Livrer un voisin à vélo","Gérer la douane","Respecter des règles étrangères","Gérer des délais de transport longs"],ex:"La livraison à vélo concerne un marché local.",ref:HS_LOG},
{k:"fill",q:"Le marché financier est un exemple de marché ___.",a:["global","local","régional","fermé"],ex:"C’est l’exemple du cours.",ref:"Leçon 4.3.1"},
{k:"qcm",q:"Quel mode de transport est typique d’un marché global ?",a:["Le conteneur maritime ou l’avion","Le vélo cargo du quartier","Le chariot à main du magasin","La livraison à pied par un coursier local"],ex:"Les longues distances demandent des transports internationaux.",ref:HS_LOG},
{k:"case",s:"Votre entreprise livre en Allemagne et en France, dans l’Union européenne.",q:"Quel document ou démarche devient important à la frontière ?",a:["Les documents de douane","Le permis de pêche","Le livret de famille","La carte de fidélité du client"],ex:"La Suisse n’est pas membre de l’UE : les envois passent la douane.",ref:HS_LOG},
{k:"tf",q:"Plus un marché est grand, plus la chaîne logistique est en général longue et complexe.",v:true,ex:"Distances, intermédiaires, règles et délais augmentent.",ref:HS_LOG},
{k:"case",s:"Un producteur de fromage vend au marché hebdomadaire de sa région.",q:"Quelle est la taille de son marché ?",a:["Régional","Global","International","National"],ex:"Le marché hebdomadaire est l’exemple de marché régional du cours.",ref:"Leçon 4.3.1"},
{k:"qcm",q:"Quel avantage un grand marché offre-t-il à une entreprise ?",a:["Davantage de clients potentiels","Moins de concurrents partout","Aucun transport à organiser","Des règles identiques dans tous les pays"],ex:"Plus de clients potentiels, mais aussi plus de complexité.",ref:"Leçon 4.3 · " + HS_LOG},
{k:"case",s:"Une marque de chocolat suisse lance une campagne dans plusieurs pays d’Asie.",q:"Pourquoi ne peut-elle pas copier sa publicité suisse telle quelle ?",a:["Les cultures et les règles diffèrent selon les pays","La publicité est interdite en Asie","Le chocolat ne se vend qu’en Suisse","Les clients asiatiques ne regardent pas de publicité"],ex:"Une entreprise globale doit tenir compte des facteurs culturels et réglementaires.",ref:"Leçon 4.3.1"},
{k:"multi",q:"Quels défis logistiques augmentent avec la taille du marché ?",good:["Distances de transport","Délais de livraison","Formalités administratives","Coûts de transport"],bad:["Contact personnel avec chaque client","Nombre de trajets à vélo"],ex:"Plus le marché est grand, plus ces défis augmentent.",ref:HS_LOG},
{k:"case",s:"Votre entrepôt sert uniquement les magasins d’un canton.",q:"Quelle est la taille de ce marché ?",a:["Régional","Global","International","Monétaire"],ex:"Un canton correspond à une région.",ref:"Leçon 4.3.1"},
{k:"qcm",q:"Comment s’appelle le marché suisse de la téléphonie mobile dans le cours ?",a:["Un marché national","Un marché local","Un marché global","Un marché fermé"],ex:"C’est l’exemple de marché national.",ref:"Leçon 4.3.1"},
{k:"case",s:"Une boutique en ligne suisse reçoit des commandes du Canada.",q:"Que doit-elle prévoir pour livrer ces clients ?",a:["Un transporteur international et les papiers de douane","Un livreur à vélo du quartier pour aller plus vite","Un simple timbre de lettre suisse collé sur le colis","Rien de plus que pour une livraison en Suisse"],ex:"Vendre au-delà des frontières demande une logistique internationale.",ref:HS_LOG},
{k:"tf",q:"Une entreprise locale doit tenir compte de nombreux facteurs culturels et réglementaires étrangers.",v:false,ex:"C’est surtout le cas des entreprises globales.",ref:"Leçon 4.3.1"}
]},
/* ============ 6 · MARCHÉS FERMÉS ============ */
{code:"M204.6", t:"Les marchés fermés", g:"Je peux décrire les mécanismes d’accès aux marchés fermés, en expliquant les restrictions telles que les licences, concessions et exigences de capital minimum.", col:"emerald", ic:"lock",
ch:[
{k:"qcm",q:"Qu’est-ce qui limite l’accès à un marché fermé ?",a:["Des règles économiques ou juridiques","La couleur des produits proposés","Le nombre de clients satisfaits","La météo de la région concernée"],ex:"Le cours définit le marché fermé par un accès limité par des règles économiques ou juridiques.",ref:"Leçon 4.2.1"},
{k:"multi",q:"Quelles restrictions peuvent limiter l’accès à un marché ?",good:["Une licence","Une concession","Un capital minimum"],bad:["Un logo coloré","Une carte de fidélité"],ex:"Ce sont les trois mécanismes cités par l’objectif.",ref:HS_ACC},
{k:"qcm",q:"Qu’est-ce qu’une concession ?",a:["Un droit accordé par l’autorité d’exercer une activité","Un rabais accordé à un client fidèle chaque année","Un contrat secret passé entre deux concurrents","Une taxe perçue sur toutes les importations"],ex:"Exemple du cours : les taxis avec concession.",ref:"Leçon 4.2.1 · " + HS_ACC},
{k:"qcm",q:"Qu’est-ce qu’une licence ?",a:["Une autorisation nécessaire pour exercer ou vendre","Une facture envoyée par un fournisseur","Un bulletin de livraison signé par le client","Un rabais accordé sur une grande quantité"],ex:"Sans licence, on ne peut pas entrer sur certains marchés (par exemple la vente d’alcool dans certains cantons).",ref:HS_ACC},
{k:"num",q:"Quel est le capital-actions minimum pour fonder une SA en Suisse (en francs) ?",n:100000,tol:0,u:"CHF",ex:"100 000 francs, dont au moins 50 000 francs libérés à la fondation (art. 621 CO).",ref:HS_CO},
{k:"num",q:"Quel est le capital social minimum pour fonder une Sàrl en Suisse (en francs) ?",n:20000,tol:0,u:"CHF",ex:"20 000 francs, entièrement libérés (art. 773 CO).",ref:HS_CO},
{k:"case",s:"Deux amis veulent fonder une SA de transport, mais ils n’ont que 30 000 francs.",q:"Quel obstacle rencontrent-ils ?",a:["Le capital minimum d’une SA est de 100 000 francs","Une SA doit compter au moins cinquante employés","Une SA n’a pas le droit de faire du transport","Il leur faut l’accord écrit de tous leurs concurrents"],ex:"Le capital minimum est une barrière d’accès. Avec 20 000 francs, une Sàrl serait possible.",ref:HS_CO},
{k:"case",s:"Une entreprise veut distribuer des lettres de moins de 50 grammes partout en Suisse.",q:"Pourquoi ne le peut-elle pas ?",a:["La Poste a un monopole sur ces lettres","Ce marché est ouvert à tous sans condition","Il suffit d’acheter une concession de taxi","La loi interdit d’envoyer des lettres"],ex:"La Confédération concède à la Poste un monopole sur les lettres jusqu’à 50 g.",ref:HS_POSTE},
{k:"tf",q:"La Poste suisse a un monopole sur les lettres jusqu’à 50 grammes.",v:true,ex:"C’est le « monopole résiduel » de la Poste.",ref:HS_POSTE},
{k:"tf",q:"Les colis jusqu’à 20 kg font partie du monopole de la Poste.",v:false,ex:"Les colis sont ouverts à la concurrence ; le monopole ne concerne que les lettres jusqu’à 50 g.",ref:HS_POSTE},
{k:"sort",q:"Marché ouvert ou marché fermé (ou limité) ?",c:["Ouvert","Fermé ou limité"],it:[["Vendre des t-shirts en ligne",0],["Exploiter un taxi avec concession",1],["Distribuer des lettres de 20 g",1],["Ouvrir un magasin de vélos",0],["Changer de caisse maladie",0],["Exploiter une ligne ferroviaire",1]],ex:"Concessions, monopoles et autorisations ferment ou limitent l’accès.",ref:"Leçon 4.2.1 · " + HS_ACC},
{k:"qcm",q:"Pourquoi l’État peut-il fermer ou limiter un marché ?",a:["Pour garantir un service public ou éviter la saturation","Pour augmenter le prix de tous les produits vendus","Pour supprimer tous les emplois de ce secteur","Pour favoriser une entreprise amie du gouvernement"],ex:"Exemples du cours : services publics (Poste, CFF) et taxis (éviter la saturation).",ref:"Leçon 4.2.1"},
{k:"match",q:"Associez chaque restriction à un exemple.",p:[["Concession","Licence de taxi de la ville"],["Monopole légal","Lettres jusqu’à 50 g"],["Capital minimum","100 000 francs pour une SA"]],ex:"Chaque mécanisme ferme ou limite l’accès à sa manière.",ref:HS_ACC},
{k:"case",s:"Un chauffeur veut exploiter un taxi en ville, mais toutes les concessions sont déjà attribuées.",q:"Quelle solution a-t-il ?",a:["Attendre une concession libre ou travailler pour un titulaire","Rouler sans concession en proposant des prix plus bas","Créer une SA pour pouvoir contourner la règle de la ville","Demander simplement l’accord de ses premiers clients"],ex:"Sur un marché limité, sans concession, on ne peut pas exercer en indépendant.",ref:"Leçon 4.2.1 · " + HS_ACC},
{k:"odd",q:"Lequel n’est pas un mécanisme d’accès aux marchés fermés ?",a:["Un rabais de fidélité","Une licence","Une concession","Un capital minimum"],ex:"Le rabais est un outil de vente, pas une barrière d’accès.",ref:HS_ACC},
{k:"fill",q:"Un taxi ne peut circuler dans certaines villes qu’avec une ___.",a:["concession","facture","palette","quittance"],ex:"C’est l’exemple du marché limité.",ref:"Leçon 4.2.1"},
{k:"qcm",q:"Quels exemples de marchés fermés le cours cite-t-il ?",a:["Des services publics comme la Poste et les CFF","Les marchés de Noël des grandes villes","Les caisses d’assurance maladie du pays","Les boutiques de vêtements du centre-ville"],ex:"Services publics en Suisse : la Poste, les CFF.",ref:"Leçon 4.2.1"},
{k:"case",s:"Une start-up veut faire rouler ses propres trains de voyageurs sur le réseau suisse.",q:"Que doit-elle obtenir ?",a:["Une concession et l’accès au réseau","Seulement un site Internet","Une simple carte de visite","L’accord de ses premiers clients"],ex:"Le transport ferroviaire est un marché fermé, soumis à concession.",ref:"Leçon 4.2.1 · " + HS_ACC},
{k:"qcm",q:"Quel est l’effet d’un capital minimum élevé ?",a:["Il rend l’entrée sur le marché plus difficile","Il supprime toute concurrence sur le marché","Il fait baisser les prix pour les clients","Il oblige l’État à aider financièrement l’entreprise"],ex:"Un capital minimum est une barrière financière à l’entrée.",ref:HS_ACC},
{k:"order",q:"Remettez dans l’ordre les démarches pour entrer sur un marché soumis à concession.",a:["Se renseigner sur les conditions","Préparer le dossier","Déposer la demande à l’autorité","Recevoir la concession","Commencer l’activité"],ex:"Sans concession accordée, pas d’activité.",ref:HS_ACC},
{k:"tf",q:"Pour une Sàrl, le capital social minimum doit être entièrement libéré à la fondation.",v:true,ex:"20 000 francs entièrement versés ou couverts par des apports en nature.",ref:HS_CO},
{k:"case",s:"Un restaurateur veut vendre de l’alcool dans son nouvel établissement.",q:"De quoi a-t-il besoin en général ?",a:["D’une autorisation ou licence du canton","D’un monopole de la Confédération","D’un capital de 100 000 francs","De l’accord des restaurants voisins"],ex:"La vente d’alcool est soumise à autorisation cantonale : l’accès est limité.",ref:HS_ACC},
{k:"case",s:"Un client vous demande pourquoi lui seul, la Poste, peut acheminer sa lettre de 20 grammes, alors que plusieurs entreprises livrent ses colis.",q:"Pourquoi la Confédération accorde-t-elle ce monopole à la Poste ?",a:["Pour financer le service universel dans tout le pays","Pour augmenter les bénéfices de ses concurrents","Pour interdire l’envoi de colis par des privés","Pour supprimer peu à peu les boîtes aux lettres"],ex:"Les recettes du monopole résiduel contribuent au financement du service universel.",ref:HS_POSTE},
{k:"case",s:"Une entreprise privée de coursiers veut livrer des enveloppes de 200 g en Suisse.",q:"Peut-elle le faire ?",a:["Oui : au-dessus de 50 g, le marché est ouvert","Non : toutes les lettres sont réservées à la Poste","Non : il lui faut un capital de 1 million","Oui, mais seulement le dimanche"],ex:"Le monopole ne couvre que les lettres jusqu’à 50 g.",ref:HS_POSTE},
{k:"case",s:"Une entreprise étrangère veut s’installer en Suisse et vendre du matériel médical.",q:"Pourquoi ce marché est-il plus difficile d’accès qu’un marché de t-shirts ?",a:["Il faut des autorisations pour vendre des produits médicaux","Les Suisses n’achètent jamais de matériel médical à l’étranger","Les t-shirts sont un monopole d’État dans tous les cantons","Le matériel médical est totalement interdit en Suisse"],ex:"Des règles juridiques (autorisations) limitent l’accès à certains marchés.",ref:HS_ACC}
]},
/* ============ 7 · LE MONOPOLE ============ */
{code:"M204.7", t:"Le monopole", g:"Je peux analyser les causes et les conséquences d’un monopole sur un marché, en expliquant comment il influence les prix et les stratégies des entreprises concurrentes.", col:"sky", ic:"crown",
ch:[
{k:"qcm",q:"Qu’est-ce qu’un monopole ?",a:["Un seul fournisseur, sans concurrence","Quelques grands fournisseurs","Beaucoup de fournisseurs et de clients","Un seul client face à plusieurs fournisseurs"],ex:"Monopole : un seul fournisseur sans concurrence.",ref:"Leçon 4.2.2"},
{k:"multi",q:"Quelles peuvent être les causes d’un monopole ?",good:["Une loi qui réserve le marché","Un réseau coûteux impossible à doubler","Un brevet qui protège une invention"],bad:["Une forte concurrence","Des milliers de petits vendeurs"],ex:"Monopole légal, monopole « naturel » (réseaux) ou protection d’une invention.",ref:HS_MONO},
{k:"qcm",q:"Quel est le risque principal d’un monopole pour les clients ?",a:["Des prix plus élevés, faute de concurrence","Des prix qui baissent toujours davantage","Trop de choix de produits pour le client","Des livraisons bien trop rapides"],ex:"Sans concurrent, le fournisseur peut fixer des prix plus élevés.",ref:HS_MONO},
{k:"tf",q:"Un monopole pousse fortement l’entreprise à innover pour garder ses clients.",v:false,ex:"Sans concurrence, la pression pour innover et baisser les prix est faible.",ref:HS_MONO},
{k:"case",s:"Une seule entreprise exploite le gazoduc d’une région. Les ménages n’ont pas d’autre fournisseur de gaz.",q:"Quelle est la cause de ce monopole ?",a:["Un réseau coûteux qu’il serait absurde de doubler","Une mauvaise qualité du service rendu aux ménages","Un grand nombre de concurrents dans la région","Un marché hebdomadaire de produits régionaux"],ex:"Pour les réseaux (gaz, eau, rail), un seul réseau est plus rationnel : c’est un monopole « naturel ».",ref:"Leçon 4.2.2 · " + HS_MONO},
{k:"case",s:"Une entreprise invente un nouveau type de palette et la protège par un brevet.",q:"Quel effet le brevet a-t-il sur le marché de cette palette ?",a:["Elle est seule à pouvoir la fabriquer pendant un temps","Tous les concurrents peuvent désormais la copier librement","Le prix de la palette baisse aussitôt de moitié","Le marché de cette palette devient un polypole"],ex:"Le brevet crée un monopole temporaire sur l’invention.",ref:HS_MONO},
{k:"qcm",q:"Pourquoi l’État surveille-t-il souvent les prix d’un monopole ?",a:["Pour éviter que les clients paient trop cher","Pour augmenter les impôts payés par les clients","Pour obliger le monopole à fermer rapidement","Pour encourager la publicité de l’entreprise"],ex:"En Suisse, par exemple, une autorité surveille la Poste et ses prix.",ref:HS_MONO},
{k:"case",s:"Le monopole de la Poste ne couvre que les lettres jusqu’à 50 g. Pour les colis, plusieurs entreprises sont en concurrence.",q:"Quelle stratégie les concurrents adoptent-ils sur les colis ?",a:["Se démarquer par le prix, le délai ou le service","Laisser tous les colis à la Poste sans réagir","Attendre patiemment la fin du monopole des lettres","Copier exactement tous les tarifs de la Poste"],ex:"Hors monopole, la concurrence pousse à se différencier.",ref:HS_POSTE},
{k:"sort",q:"Conséquence d’un monopole ou d’une forte concurrence ?",c:["Monopole","Forte concurrence"],it:[["Prix plus élevés",0],["Grand choix pour le client",1],["Peu d’innovation",0],["Promotions fréquentes",1],["Client sans alternative",0],["Recherche de nouveaux services",1]],ex:"La concurrence profite au client ; le monopole l’enferme.",ref:HS_MONO},
{k:"match",q:"Associez chaque cause à un exemple de monopole.",p:[["Réseau","Conduites d’eau d’une ville"],["Loi","Lettres jusqu’à 50 g"],["Brevet","Une invention protégée"]],ex:"Ce sont trois causes fréquentes de monopole.",ref:"Leçon 4.2.2 · " + HS_MONO},
{k:"odd",q:"Lequel n’est pas une conséquence habituelle d’un monopole ?",a:["Une baisse des prix due à la concurrence","Des prix plus élevés","Un client sans alternative","Peu de pression pour innover"],ex:"Il n’y a justement pas de concurrence dans un monopole.",ref:HS_MONO},
{k:"fill",q:"Dans un monopole, l’absence de ___ permet au fournisseur de fixer des prix plus élevés.",a:["concurrence","clients","stock","transport"],ex:"Sans concurrent, le client n’a pas d’alternative.",ref:HS_MONO},
{k:"case",s:"Une entreprise de logistique dépend d’un seul fournisseur de pièces de rechange pour ses chariots, protégé par un brevet.",q:"Quel risque court-elle ?",a:["Des prix élevés et aucun moyen de négocier","Trop d’offres concurrentes à comparer","Une baisse automatique des prix","Aucun risque : le brevet protège le client"],ex:"Face à un monopole, le client a peu de pouvoir de négociation.",ref:HS_MONO},
{k:"tf",q:"Dans un monopole, le client peut facilement changer de fournisseur.",v:false,ex:"Il n’y a qu’un seul fournisseur.",ref:"Leçon 4.2.2"},
{k:"qcm",q:"Quels exemples de monopole le cours cite-t-il ?",a:["Gazoducs, conduites d’eau, réseau de transport","Pétrole, électricité, réseau de téléphonie mobile","Marché hebdomadaire et location de logements","Un employeur unique face à plusieurs candidats"],ex:"Les autres exemples sont des oligopoles, des polypoles et un monopsone.",ref:"Leçon 4.2.2"},
{k:"order",q:"Remettez dans l’ordre l’enchaînement qui mène à des prix élevés dans un monopole.",a:["Un seul fournisseur sur le marché","Aucun concurrent pour comparer","Le client n’a pas d’alternative","Le fournisseur fixe un prix plus élevé"],ex:"L’absence d’alternative donne au fournisseur le pouvoir de fixer le prix.",ref:HS_MONO},
{k:"case",s:"La fin d’un brevet permet à d’autres entreprises de fabriquer un médicament.",q:"Que se passe-t-il en général sur le prix ?",a:["Il baisse grâce à l’arrivée de concurrents","Il augmente fortement dès l’année suivante","Il reste toujours exactement le même","Le médicament disparaît aussitôt du marché"],ex:"Avec la concurrence (génériques), les prix baissent.",ref:HS_MONO},
{k:"case",s:"Une ville confie à une seule entreprise le ramassage des déchets pour dix ans.",q:"Comment la ville peut-elle éviter les abus de prix ?",a:["Fixer les prix et la qualité dans le contrat","Laisser l’entreprise décider seule de tout","Interdire le ramassage des déchets","Engager cinq entreprises pour la même rue"],ex:"Un monopole accordé s’accompagne de règles et de contrôles.",ref:HS_MONO},
{k:"multi",q:"Quelles stratégies une entreprise concurrente peut-elle adopter face à un monopole ?",good:["Viser un marché voisin non réservé","Proposer un service différent","Innover avec un produit de substitution"],bad:["Copier le produit breveté","Ignorer complètement le marché"],ex:"Les concurrents contournent le monopole par des marchés ou produits voisins.",ref:HS_MONO},
{k:"case",s:"Les lettres de moins de 50 g sont réservées à la Poste. Une entreprise privée développe un service de courrier électronique sécurisé pour les factures.",q:"Quelle stratégie utilise-t-elle ?",a:["Proposer un produit de substitution","Entrer illégalement dans le monopole","Racheter la Poste","Baisser le prix des timbres"],ex:"Un produit de substitution permet de concurrencer indirectement un monopole.",ref:HS_POSTE + " · " + HS_MONO},
{k:"qcm",q:"Que signifie « monopole naturel » ?",a:["Un réseau qu’il vaut mieux ne construire qu’une fois","Un monopole sur la vente des produits biologiques","Un marché sur lequel aucune règle ne s’applique","Un marché réservé aux seuls agriculteurs suisses"],ex:"Doubler un réseau d’eau ou de rail coûterait trop cher.",ref:HS_MONO},
{k:"tf",q:"Un monopole peut être accordé par la loi pour garantir un service public.",v:true,ex:"Exemple : le monopole des lettres jusqu’à 50 g finance le service universel de la Poste.",ref:HS_POSTE},
{k:"case",s:"Dans une petite île, un seul magasin vend des produits alimentaires.",q:"Quel comportement des prix peut-on attendre ?",a:["Des prix plus élevés que sur le continent","Des prix plus bas que partout ailleurs","Des promotions affichées tous les jours","Des prix fixés directement par les clients"],ex:"Seul fournisseur, le magasin n’a pas à s’aligner sur des concurrents.",ref:HS_MONO},
{k:"qcm",q:"Comment l’arrivée d’un concurrent change-t-elle un ancien monopole ?",a:["Le client gagne le choix et les prix sont mis sous pression","Rien ne change pour le client, ni le prix ni le choix","Les prix augmentent encore plus qu’avant l’ouverture","Le marché devient alors un monopsone d’État"],ex:"La concurrence redonne du pouvoir au client.",ref:HS_MONO},
{k:"case",s:"Votre dépôt doit choisir un fournisseur d’électricité, mais votre commune n’en propose qu’un pour les petits clients.",q:"Que pouvez-vous faire pour réduire votre dépendance ?",a:["Produire une partie de son électricité avec des panneaux solaires","Changer de fournisseur d’électricité chaque semaine","Négocier un prix deux fois plus bas avec le fournisseur unique","Ne plus utiliser du tout d’électricité au dépôt"],ex:"Face à un fournisseur unique, une solution de substitution réduit la dépendance.",ref:HS_MONO}
]}
];

window.LEVELS=[[0,"Stagiaire"],[150,"Apprenti·e logisticien·ne"],[400,"Logisticien·ne en formation"],[800,"Logisticien·ne CFC"],[1300,"Référent·e marchés"],[2000,"Expert·e économie logistique"],[3000,"Formateur·rice logistique"]];

